O=Path('vitaliza_tidy_eda');J=json.loads((O/'dados_eda.json').read_text());M=J['meta'];D={k:pd.DataFrame(v) for k,v in J.items() if k!='meta'}
def n(v):return f'{int(v):,}'.replace(',','.')
def pct(v,dec=2):return f'{100*v:.{dec}f}%'.replace('.',',')
def money(v):return 'R$ '+f'{v:,.2f}'.replace(',','X').replace('.',',').replace('X','.')
def tbl(d,percent=(),currency=()):
 v=d.copy()
 for c in v:
  if c in percent:v[c]=v[c].map(lambda x:'—' if pd.isna(x) else pct(x))
  elif c in currency:v[c]=v[c].map(lambda x:'—' if pd.isna(x) else money(x))
  elif pd.api.types.is_float_dtype(v[c]):v[c]=v[c].map(lambda x:'—' if pd.isna(x) else f'{x:,.3f}'.replace(',','X').replace('.',',').replace('X','.'))
 return '<div class="table-wrap">'+v.to_html(index=False,border=0)+'</div>'
def box(title,text,warning=False):return '<aside class="callout '+('warning' if warning else '')+'"><b>'+title+'</b><p>'+text+'</p></aside>'
def source(s):return '<p class="source">'+s+'</p>'
def graph(f,id,height=380):
 f.update_layout(template='plotly_white',height=height,margin=dict(l=65,r=25,t=45,b=65),font=dict(family='Arial',size=12,color='#27384a'),colorway=['#167e77','#7655b5','#e8846f','#7b9eaf'],paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='rgba(0,0,0,0)',legend=dict(orientation='h',y=1.17))
 f.update_xaxes(automargin=True);f.update_yaxes(automargin=True)
 return f.to_html(full_html=False,include_plotlyjs=False,div_id='eda-'+id,config={'responsive':True,'displaylogo':False})
